{"Table":"kersef_tb_power_level","Create Table":"CREATE TABLE `kersef_tb_power_level` (\n  `id` varchar(36) NOT NULL,\n  `nick` varchar(255) NOT NULL,\n  `class` varchar(255) NOT NULL,\n  `focus` varchar(255) NOT NULL,\n  `score` int(11) NOT NULL,\n  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),\n  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),\n  `guildId` varchar(255) NOT NULL,\n  `userId` varchar(255) NOT NULL,\n  PRIMARY KEY (`id`),\n  KEY `FK_power_user_guild` (`guildId`),\n  KEY `FK_power_user_user` (`userId`),\n  CONSTRAINT `FK_power_user_guild` FOREIGN KEY (`guildId`) REFERENCES `kersef_tb_user` (`guildId`) ON DELETE CASCADE ON UPDATE CASCADE,\n  CONSTRAINT `FK_power_user_user` FOREIGN KEY (`userId`) REFERENCES `kersef_tb_user` (`userId`) ON DELETE CASCADE ON UPDATE CASCADE\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci","json":{"name":"kersef_tb_power_level.sql","path":"files/sql/rod/kersef_tb_power_level.sql","sha":"021bf406f3edc9dddda4454642ac8316ba2d7d3f","size":1386952,"url":"https://api.github.com/repos/rodcordeiro/shares/contents/files/sql/rod/kersef_tb_power_level.sql?ref=master","html_url":"https://github.com/rodcordeiro/shares/blob/master/files/sql/rod/kersef_tb_power_level.sql","git_url":"https://api.github.com/repos/rodcordeiro/shares/git/blobs/021bf406f3edc9dddda4454642ac8316ba2d7d3f","download_url":"https://raw.githubusercontent.com/rodcordeiro/shares/master/files/sql/rod/kersef_tb_power_level.sql","type":"file","content":"","encoding":"none","_links":{"self":"https://api.github.com/repos/rodcordeiro/shares/contents/files/sql/rod/kersef_tb_power_level.sql?ref=master","git":"https://api.github.com/repos/rodcordeiro/shares/git/blobs/021bf406f3edc9dddda4454642ac8316ba2d7d3f","html":"https://github.com/rodcordeiro/shares/blob/master/files/sql/rod/kersef_tb_power_level.sql"}},"pairedItem":{"item":29},"index":29}